
#include <stdio.h>

int main() {

    // Criar variáveis e passar os valores
    int x = 15;
    int y = 25;

    // Criar variável que recebe a soma
    int soma = x + y;

    // Exibir os valores
    printf("Valor do x é: %d\n", x);
    printf("O valor do y é: %d\n", y);
    printf("A soma é: %d\n", soma);

    return 0;
}